-- 30_books_webnovel_samples.sql
-- MetaFusion 经典图书、网络文学、世界名著、轻小说与官方设定集核心种子数据集 (55部经典作品)
-- 固定 UUID 前缀 bb000000-0000-4000-8000-
-- 遵循 LRM 规范：纯净作品名、Release 分卷呈现、多维标签体系、work_translations、cover_aspect = '3:4'

BEGIN;

SELECT setval(pg_get_serial_sequence('tags', 'id'), COALESCE((SELECT MAX(id) FROM tags), 1));

-- ---------------------------------------------------------------------------
-- 0. 标签扩充 (Tags)
-- ---------------------------------------------------------------------------
ON CONFLICT (name) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 1. 创作者与出版社 (Artists / Authors / Studios / Publishers)
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    original_name = EXCLUDED.original_name,
    disambiguation = EXCLUDED.disambiguation,
    biography = EXCLUDED.biography,
    country = EXCLUDED.country,
    external_ids = EXCLUDED.external_ids;

-- 艺术家多语言翻译 (Artist Translations)
ON CONFLICT (artist_id, locale) DO UPDATE SET name = EXCLUDED.name, biography = EXCLUDED.biography;

-- ---------------------------------------------------------------------------
-- 2. 作品库 (Works - 55部高质量图书与网络文学作品)
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    original_title = EXCLUDED.original_title,
    aliases = EXCLUDED.aliases,
    summary = EXCLUDED.summary,
    cover_image_url = EXCLUDED.cover_image_url,
    cover_aspect = EXCLUDED.cover_aspect,
    catalog_metadata = EXCLUDED.catalog_metadata;

-- 作品多语言翻译 (Work Translations)
ON CONFLICT (work_id, locale) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary;

-- 作品标签关联 (Work Tag Relations)
